// Copies src-tauri/android-overrides/** over the project generated by `tauri android init`,
// then patches the generated AndroidManifest.xml.
import { cpSync, existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const source = join(root, 'src-tauri', 'android-overrides');
const target = join(root, 'src-tauri', 'gen', 'android');

if (!existsSync(target)) {
  console.error(`[android-overrides] ${relative(root, target)} not found, run "tauri android init" first.`);
  process.exit(1);
}

function listFiles(dir) {
  return readdirSync(dir).flatMap((name) => {
    const full = join(dir, name);
    return statSync(full).isDirectory() ? listFiles(full) : [full];
  });
}

for (const file of listFiles(source)) {
  const rel = relative(source, file);
  cpSync(file, join(target, rel));
  console.log(`[android-overrides] ${rel}`);
}

const manifestPath = join(target, 'app', 'src', 'main', 'AndroidManifest.xml');
let manifest = readFileSync(manifestPath, 'utf8');
// Many video sources only serve plain http.
manifest = manifest.replace(/android:usesCleartextTraffic="[^"]*"/, 'android:usesCleartextTraffic="true"');
if (!manifest.includes('android:usesCleartextTraffic')) {
  manifest = manifest.replace('<application', '<application\n        android:usesCleartextTraffic="true"');
}
if (!manifest.includes('android:resizeableActivity')) {
  manifest = manifest.replace('<application', '<application\n        android:resizeableActivity="true"');
}
writeFileSync(manifestPath, manifest);
console.log('[android-overrides] patched AndroidManifest.xml');
